mapper.select:
  select a.REGIST_SEQNO from (
    SELECT
    @rownum := @rownum + 1 rownum,
    REGIST_SEQNO,
    IF
    (
      (
      @POS_DATE = A.POS_DATE
      AND @PLAN_ASSET_ID = A.PLAN_ASSET_ID
      AND @ASSET_CODE = A.ASSET_CODE
      ),
      @rank := @rank + 1,
      @rank := 1
    ) AS myrank,
    @POS_DATE := A.POS_DATE,
    @PLAN_ASSET_ID := A.PLAN_ASSET_ID,
    @ASSET_CODE := A.ASSET_CODE
    FROM
    ( SELECT * FROM CHB_BOT_AST_POS_SUB_HIS ORDER BY POS_DATE,PLAN_ASSET_ID, ASSET_CODE, ifnull( UPDATE_TIME, CREATE_TIME ) DESC ) A,
    (
    SELECT
    @rownum := 0,
    @POS_DATE := NULL,
    @PLAN_ASSET_ID := NULL,
    @ASSET_CODE := NULL,
    @rank := 0
    ) B
  where 

   POS_DATE = #{item.posDate}
	and PLAN_ASSET_ID = #{item.planAssetId}
	and ASSET_CODE = #{item.assetCode}

  )a
  where 1 = 1 limit 1
